using Microsoft.EntityFrameworkCore;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF 9 changed the default from "Discriminator" to "$type".
            // Existing documents and direct SQL queries use "Discriminator",
            // so we keep the old name to stay compatible.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed.
            // EF 8 stored the JSON "id" as "Product|<key>" via a shadow property.
            // EF 9 defaults to using the raw key value.
            // Restore old format so EF can look up existing 500K documents.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator((_, _) => new LegacyCosmosIdGenerator());

            // BREAKING CHANGE 3 — HasIndex not supported.
            // The Cosmos provider never enforced indexes; EF 9 now throws.
            // Removed the HasIndex(p => p.Sku) call that was here.
            // Manage indexing policy directly in Azure portal / Bicep / ARM.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

// Generates JSON "id" values in the legacy "EntityType|Key" format used by EF Core 8.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => true;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
}

